import "./styles.css";
import defenseWorkbook from "./data/defense-workbook.json";

const budgetCategories = [
  ["計畫主持人",180000,"personnel"],["協同計畫主持人",288000,"personnel"],["碩士級專案助理本薪(含勞健保勞工自付額)",599976,"personnel"],["碩士級專案助理雇主負擔之勞健保及勞工退休金",114588,"personnel"],["碩士級專案助理年終獎金",74997,"personnel"],["學士級專案助理本薪(含勞健保勞工自付額)",529056,"personnel"],["學士級專案助理雇主負擔之勞健保及勞工退休金",108264,"personnel"],["學士級專案助理年終獎金",66132,"personnel"],["兼任助理本薪(含勞健保勞工自付額)",720000,"personnel"],["兼任助理雇主負擔之勞健保及勞工退休金",143232,"personnel"],["加班費",200000,"personnel"],["二代健保補充保費",12853,"personnel"],["專家學者出席費",90000,"operating"],["教育訓練講座鐘點費",96000,"operating"],["運動防護員/緊急醫療救護技術員/物理治療師工作費",1900000,"operating"],["醫師費",88000,"operating"],["運動防護專長生工作費",3626000,"operating"],["公提二代健保補充保費(b)",122380,"operating"],["運動防護材料費",239794,"operating"],["機能重建材料費",239794,"operating"],["物理治療材料費",239794,"operating"],["差旅費",105510,"operating"],["印刷費",57551,"operating"],["餐費",76734,"operating"],["宣傳品製作費",47959,"operating"],["資料蒐集費",57551,"operating"],["設備維護費",19184,"operating"],["運費",28775,"operating"],["租金",95918,"operating"],["記者會/宣傳影片",28775,"operating"],["雜支",34758,"operating"],["行政管理費(含稅)",493290,"admin"]
].map(([name,budget,group],i)=>({id:`cat-${i+1}`,name,budget,adjustment:0,spent:0,group}));

const initialState = {
  activeRole:"admin",
  projects:[
    {id:"defense",name:"115年防護計畫",code:"115014",source:"臺北市體育局",budget:10724865,categories:budgetCategories,visible:true,status:"active"},
    {id:"sports-science",name:"運科計畫",code:"",source:"",budget:0,categories:[],visible:true,status:"empty"},
    {id:"ai-tech",name:"AI 科技計畫",code:"",source:"",budget:0,categories:[],visible:true,status:"empty"},
    {id:"isports",name:"運動 i 臺灣衛生局計畫",code:"",source:"",budget:0,categories:[],visible:true,status:"empty"},
    {id:"smart-spike",name:"國科會智慧鞋釘計畫",code:"",source:"國家科學及技術委員會",budget:0,categories:[],visible:true,status:"empty"},
    {id:"nmes-ntue",name:"工研院 NMES－北師大",code:"",source:"工研院",budget:230000,categories:[],visible:true,status:"planned"},
    {id:"nmes-energy",name:"工研院 NMES－能源工程學會",code:"",source:"工研院",budget:285000,categories:[],visible:true,status:"planned"},
    {id:"nmes-twsh",name:"工研院 NMES－臺灣運動健康科技學會",code:"",source:"工研院",budget:280000,categories:[],visible:true,status:"planned"}
  ],
  transactions:[],
  people:[],
  permissions:[],
  receipts:[],
  settings:{warning:80,org:"臺灣運動健康科技學會"}
};

const pages={dashboard:["經費總覽","跨計畫預算、執行率與警示"],projects:["計畫管理","預算科目、權限與計畫基本資料"],ledger:["經費登錄表","如 Excel 般直接登錄、篩選與匯出"],experts:["專家委員","報稅、聯絡及銀行資料管理"],receipts:["領據與簽名","自動帶入委員資料、列印與電子簽名"],access:["成員與權限","主持人、行政人員與可見計畫設定"]};
const nav=[["dashboard","◈","經費總覽"],["projects","▦","計畫管理"],["ledger","≣","經費登錄表"],["experts","◎","專家委員"],["receipts","▤","領據與簽名"],["access","◉","成員與權限"]];
let state=load(); let current="dashboard"; let selectedProject="defense"; let selectedPerson="";
const app=document.querySelector("#app");
function load(){try{return {...initialState,...JSON.parse(localStorage.getItem("kanpai-accounting")||"{}")};}catch{return structuredClone(initialState)}}
function save(){localStorage.setItem("kanpai-accounting",JSON.stringify(state));}
const money=n=>new Intl.NumberFormat("zh-TW",{style:"currency",currency:"TWD",maximumFractionDigits:0}).format(Number(n)||0);
const spent=p=>(p.id==="defense"?defenseSheetSpent():0)+state.transactions.filter(t=>t.projectId===p.id&&t.status!=="cancelled").reduce((s,t)=>s+Number(t.amount||0),0);
const esc=s=>String(s??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;","\"":"&quot;","'":"&#39;"}[c]));
function shell(){
 const [title,sub]=pages[current];
 app.innerHTML=`<div class="shell"><aside class="sidebar" id="sidebar"><div class="brand"><div class="brand-mark">乾</div><div><strong>乾杯會計</strong><small>PROJECT FINANCE HUB</small></div></div><nav class="nav">${nav.map(([id,icon,label])=>`<button data-page="${id}" class="${current===id?"active":""}"><span class="icon">${icon}</span>${label}</button>`).join("")}</nav><div class="sidebar-foot">總編輯模式<br>資料目前儲存於此瀏覽器</div></aside><main class="main"><header class="topbar"><div class="top-actions"><button class="btn mobile-menu" id="menuBtn">☰</button><div class="title"><h1>${title}</h1><p>${sub}</p></div></div><div class="top-actions"><span class="role-pill">總編輯 · 全部計畫</span><button class="btn" id="backupBtn">匯出備份</button></div></header><section class="content" id="content"></section></main></div>`;
 document.querySelectorAll("[data-page]").forEach(b=>b.onclick=()=>{current=b.dataset.page;shell();render();});
 document.querySelector("#menuBtn").onclick=()=>document.querySelector("#sidebar").classList.toggle("open");
 document.querySelector("#backupBtn").onclick=backup;
 render();
}
function render(){({dashboard,projects,ledger:ledgerV2,experts:expertsV2,receipts:receiptsV4,access}[current]||dashboard)();}
function dashboard(){
 const total=state.projects.reduce((s,p)=>s+Number(p.budget||0),0), used=state.projects.reduce((s,p)=>s+spent(p),0), pct=total?used/total*100:0;
 content.innerHTML=`<div class="toolbar"><div class="toolbar-left"><select class="btn" id="dashFilter"><option>全部可見計畫</option>${state.projects.map(p=>`<option>${esc(p.name)}</option>`)}</select></div><div class="toolbar-right"><span class="kpi-note">最後儲存：${new Date().toLocaleString("zh-TW")}</span></div></div><div class="grid kpis"><div class="card kpi"><div class="kpi-label">總核定預算</div><div class="kpi-value">${money(total)}</div><div class="kpi-note">${state.projects.length} 個預設計畫（含 NMES 三單位）</div></div><div class="card kpi"><div class="kpi-label">已登錄支出</div><div class="kpi-value">${money(used)}</div><div class="kpi-note">來自經費登錄表</div></div><div class="card kpi"><div class="kpi-label">可用餘額</div><div class="kpi-value">${money(total-used)}</div><div class="kpi-note">預算減已登錄支出</div></div><div class="card kpi"><div class="kpi-label">整體執行率</div><div class="kpi-value">${pct.toFixed(1)}%</div><div class="progress ${pct>=state.settings.warning?"warn":""}"><i style="width:${Math.min(pct,100)}%"></i></div><div class="kpi-note">警示門檻 ${state.settings.warning}%</div></div></div><div class="grid section-grid"><div class="card"><div class="card-title"><div><h2>計畫經費執行</h2><p>點選計畫可進入經費明細</p></div></div><div class="project-bars">${state.projects.map(p=>{let u=spent(p),q=p.budget?u/p.budget*100:0;return `<div class="project-row" data-open-project="${p.id}"><div class="project-meta"><strong>${esc(p.name)}</strong><span class="money">${money(u)} / ${money(p.budget)}</span></div><div class="progress ${q>=state.settings.warning?"warn":""}"><i style="width:${Math.min(q,100)}%"></i></div></div>`}).join("")}</div></div><div class="card"><div class="card-title"><div><h2>預算狀態</h2><p>依計畫完整性分類</p></div></div><div class="project-list">${state.projects.map(p=>`<div class="project-card" data-open-project="${p.id}"><div class="project-icon">${p.name.slice(0,1)}</div><div><h3>${esc(p.name)}</h3><p>${p.budget?`核定 ${money(p.budget)}`:"尚待匯入預算表"}</p></div><span class="status ${p.budget?"":"empty"}">${p.budget?"已建立":"待補件"}</span></div>`).join("")}</div></div></div>`;
 document.querySelectorAll("[data-open-project]").forEach(el=>el.onclick=()=>{selectedProject=el.dataset.openProject;current="ledger";shell();});
}
function projects(){
 content.innerHTML=`<div class="toolbar"><div class="toolbar-left"><button class="btn primary" id="addProject">+新增計畫</button></div><div class="toolbar-right"><span class="kpi-note">防護計畫依附件原預算科目建立</span></div></div><div class="grid" style="grid-template-columns:repeat(auto-fit,minmax(280px,1fr))">${state.projects.map(p=>`<div class="card project-detail"><div class="card-title"><div><h3>${esc(p.name)}</h3><p>${esc(p.code||"尚未設定計畫編號")} · ${esc(p.source||"經費來源待補")}</p></div><span class="status ${p.budget?"":"empty"}">${p.budget?"預算已建立":"空白"}</span></div><div class="kpi-value" style="font-size:24px">${money(p.budget)}</div><div class="kpi-note">${p.categories.length} 個預算科目 · 已用 ${money(spent(p))}</div><div class="progress" style="margin:14px 0"><i style="width:${p.budget?Math.min(spent(p)/p.budget*100,100):0}%"></i></div><button class="btn small" data-edit-project="${p.id}">編輯與查看科目</button></div>`).join("")}</div>`;
 document.querySelector("#addProject").onclick=()=>projectModal();
 document.querySelectorAll("[data-edit-project]").forEach(b=>b.onclick=()=>projectModal(state.projects.find(p=>p.id===b.dataset.editProject)));
}
function projectModal(p){
 const edit=!!p; modal(`<div class="modal-head"><h2>${edit?"編輯計畫":"新增計畫"}</h2><button class="close" data-close>&times;</button></div><form id="projectForm" class="form-grid"><div class="field full"><label>計畫名稱</label><input name="name" required value="${esc(p?.name||"")}"></div><div class="field"><label>計畫編號</label><input name="code" value="${esc(p?.code||"")}"></div><div class="field"><label>經費來源</label><input name="source" value="${esc(p?.source||"")}"></div><div class="field"><label>核定預算</label><input name="budget" type="number" min="0" value="${p?.budget||0}"></div><div class="field"><label>科目模板</label><select name="template"><option value="empty">空白（之後匯入）</option><option value="defense">套用防護計畫 32 科目</option></select></div><div class="field full"><div class="notice">套用模板只會建立科目名稱，不會複製防護計畫的預算金額或真實明細。</div></div><div class="field full"><button class="btn primary">儲存計畫</button></div></form>`);
 document.querySelector("#projectForm").onsubmit=e=>{e.preventDefault();let f=new FormData(e.target),obj=edit?p:{id:crypto.randomUUID(),categories:[],visible:true,status:"empty"};obj.name=f.get("name");obj.code=f.get("code");obj.source=f.get("source");obj.budget=Number(f.get("budget"));if(!edit&&f.get("template")==="defense")obj.categories=budgetCategories.map(c=>({...c,id:crypto.randomUUID(),budget:0,spent:0}));if(!edit)state.projects.push(obj);save();closeModal();projects();};
}
function ledger(){
 const p=state.projects.find(x=>x.id===selectedProject)||state.projects[0], tx=state.transactions.filter(t=>t.projectId===p.id), cats=p.categories;
 content.innerHTML=`<div class="toolbar"><div class="toolbar-left"><select class="btn" id="projectSelect">${state.projects.map(x=>`<option value="${x.id}" ${x.id===p.id?"selected":""}>${esc(x.name)}</option>`)}</select><button class="btn primary" id="addRow">+新增一筆</button><label class="btn" for="csvInput">匯入 CSV<input id="csvInput" type="file" accept=".csv,text/csv" hidden></label></div><div class="toolbar-right"><button class="btn" id="exportCsv">匯出 CSV</button></div></div><div class="grid kpis" style="margin-bottom:18px"><div class="card kpi"><div class="kpi-label">核定預算</div><div class="kpi-value">${money(p.budget)}</div></div><div class="card kpi"><div class="kpi-label">已登錄金額</div><div class="kpi-value">${money(spent(p))}</div></div><div class="card kpi"><div class="kpi-label">未核銷／未出帳</div><div class="kpi-value">${money(tx.filter(t=>t.status!=="reimbursed").reduce((s,t)=>s+Number(t.amount),0))}</div></div><div class="card kpi"><div class="kpi-label">餘額</div><div class="kpi-value">${money(p.budget-spent(p))}</div></div></div>${cats.length?`<div class="card" style="margin-bottom:18px"><div class="card-title"><div><h2>預算科目樞紐分析</h2><p>原預算、勻支與已用金額</p></div></div><div class="table-wrap"><table><thead><tr><th>類別</th><th>科目</th><th>原預算</th><th>勻支調整</th><th>勻支後</th><th>已用</th><th>餘額</th><th>使用率</th></tr></thead><tbody>${cats.map(c=>{let cs=tx.filter(t=>t.category===c.name).reduce((s,t)=>s+Number(t.amount),0),b=Number(c.budget)+Number(c.adjustment||0),q=b?cs/b*100:0;return `<tr><td><span class="tag">${c.group==="personnel"?"人事費":c.group==="admin"?"行管費":"業務費"}</span></td><td>${esc(c.name)}</td><td class="money">${money(c.budget)}</td><td class="money">${money(c.adjustment)}</td><td class="money">${money(b)}</td><td class="money">${money(cs)}</td><td class="money">${money(b-cs)}</td><td>${q.toFixed(1)}%</td></tr>`}).join("")}</tbody></table></div></div>`:`<div class="notice" style="margin-bottom:18px">這個計畫尚未匯入預算科目；可先登錄明細，之後再補預算表。</div>`}<div class="card"><div class="card-title"><div><h2>Excel 式經費登錄</h2><p>儲存於瀏覽器，匯入前可先下載 CSV 範本</p></div></div><div class="table-wrap"><table><thead><tr><th>日期</th><th>編號</th><th>用途說明</th><th>預算科目</th><th>狀態</th><th>金額</th><th>代墊人</th><th></th></tr></thead><tbody id="txBody">${tx.length?tx.map(t=>txRow(t,p)).join(""):`<tr><td colspan="8"><div class="empty-state"><strong>尚無登錄資料</strong>點「新增一筆」或匯入 CSV 開始。</div></td></tr>`}</tbody></table></div></div>`;
 document.querySelector("#projectSelect").onchange=e=>{selectedProject=e.target.value;ledger();};document.querySelector("#addRow").onclick=()=>{state.transactions.push({id:crypto.randomUUID(),projectId:p.id,date:new Date().toISOString().slice(0,10),number:"",description:"",category:cats[0]?.name||"",status:"pending",amount:0,payee:""});save();ledger();};
 document.querySelectorAll("[data-tx-field]").forEach(el=>el.onchange=e=>{let t=state.transactions.find(x=>x.id===el.dataset.id);t[el.dataset.txField]=el.dataset.txField==="amount"?Number(e.target.value):e.target.value;save();ledger();});
 document.querySelectorAll("[data-delete-tx]").forEach(b=>b.onclick=()=>{state.transactions=state.transactions.filter(t=>t.id!==b.dataset.deleteTx);save();ledger();});
 document.querySelector("#exportCsv").onclick=()=>downloadCsv(p,tx);document.querySelector("#csvInput").onchange=e=>importCsv(e.target.files[0],p);
}
function txRow(t,p){return `<tr><td><input type="date" data-tx-field="date" data-id="${t.id}" value="${esc(t.date)}"></td><td><input data-tx-field="number" data-id="${t.id}" value="${esc(t.number)}" placeholder="X-115..."></td><td><input data-tx-field="description" data-id="${t.id}" value="${esc(t.description)}" placeholder="用途說明"></td><td><select data-tx-field="category" data-id="${t.id}"><option value="">待分類</option>${p.categories.map(c=>`<option ${t.category===c.name?"selected":""}>${esc(c.name)}</option>`)}</select></td><td><select data-tx-field="status" data-id="${t.id}"><option value="pending" ${t.status==="pending"?"selected":""}>未出帳</option><option value="borrowed" ${t.status==="borrowed"?"selected":""}>預借</option><option value="reimbursed" ${t.status==="reimbursed"?"selected":""}>已核銷</option></select></td><td><input type="number" min="0" data-tx-field="amount" data-id="${t.id}" value="${t.amount}"></td><td><input data-tx-field="payee" data-id="${t.id}" value="${esc(t.payee)}"></td><td><button class="btn small danger" data-delete-tx="${t.id}">刪除</button></td></tr>`}
function experts(){content.innerHTML=`<div class="toolbar"><div class="toolbar-left"><button class="btn primary" id="addPerson">+新增委員</button><label class="btn" for="peopleCsv">匯入名單 CSV<input id="peopleCsv" type="file" accept=".csv" hidden></label></div><div class="toolbar-right"><span class="kpi-note">敏感欄位預設遮罩</span></div></div><div class="notice" style="margin-bottom:18px">身分證、戶籍與銀行資料屬敏感個資；目前版本只儲存在本機瀏覽器，未寫入公開網站。</div><div class="card"><div class="table-wrap"><table><thead><tr><th>姓名</th><th>電話</th><th>Email</th><th>身分證</th><th>戶籍地址</th><th>銀行</th><th></th></tr></thead><tbody>${state.people.length?state.people.map(p=>`<tr><td><strong>${esc(p.name)}</strong></td><td>${esc(p.phone)}</td><td>${esc(p.email)}</td><td>${p.idNo?esc(p.idNo.slice(0,3)+"•••••"+p.idNo.slice(-2)):"—"}</td><td>${p.address?esc(p.address.slice(0,6)+"…"):"—"}</td><td>${esc(p.bank||"—")}</td><td><button class="btn small" data-person="${p.id}">查看／製作領據</button></td></tr>`).join(""):`<tr><td colspan="7"><div class="empty-state"><strong>尚無專家委員</strong>新增委員後，可一鍵帶入領據。</div></td></tr>`}</tbody></table></div></div>`;document.querySelector("#addPerson").onclick=()=>personModal();document.querySelectorAll("[data-person]").forEach(b=>b.onclick=()=>personModal(state.people.find(p=>p.id===b.dataset.person)));}
function personModal(p){const edit=!!p;modal(`<div class="modal-head"><h2>${edit?"委員資料":"新增委員"}</h2><button class="close" data-close>&times;</button></div><form id="personForm" class="form-grid"><div class="field"><label>姓名</label><input required name="name" value="${esc(p?.name||"")}"></div><div class="field"><label>出生年月日</label><input type="date" name="birthday" value="${esc(p?.birthday||"")}"></div><div class="field"><label>身分證字號／居留證</label><input name="idNo" value="${esc(p?.idNo||"")}"></div><div class="field"><label>聯絡電話</label><input name="phone" value="${esc(p?.phone||"")}"></div><div class="field"><label>Email</label><input type="email" name="email" value="${esc(p?.email||"")}"></div><div class="field"><label>戶籍地址</label><input name="address" value="${esc(p?.address||"")}"></div><div class="field"><label>銀行／郵局</label><input name="bank" value="${esc(p?.bank||"")}"></div><div class="field"><label>分行／局號</label><input name="branch" value="${esc(p?.branch||"")}"></div><div class="field"><label>帳號</label><input name="account" value="${esc(p?.account||"")}"></div><div class="field"><label>戶名</label><input name="accountName" value="${esc(p?.accountName||"")}"></div><div class="field full"><button class="btn primary">儲存委員</button>${edit?` <button type="button" class="btn gold" id="toReceipt">帶入製作領據</button>`:""}</div></form>`);document.querySelector("#personForm").onsubmit=e=>{e.preventDefault();let data=Object.fromEntries(new FormData(e.target));if(edit)Object.assign(p,data);else state.people.push({id:crypto.randomUUID(),...data});save();closeModal();experts();};if(edit)document.querySelector("#toReceipt").onclick=()=>{selectedPerson=p.id;closeModal();current="receipts";shell();};}
function receipts(){let person=state.people.find(p=>p.id===selectedPerson)||state.people[0]||{},today=new Date().toISOString().slice(0,10);content.innerHTML=`<div class="receipt-layout"><div class="card receipt-controls no-print"><div class="card-title"><div><h2>領據設定</h2><p>即時預覽並列印成 PDF</p></div></div><div class="form-grid"><div class="field full"><label>領款人</label><select id="receiptPerson"><option value="">請選擇委員</option>${state.people.map(p=>`<option value="${p.id}" ${p.id===person.id?"selected":""}>${esc(p.name)}</option>`)}</select></div><div class="field full"><label>抬頭與 Logo</label><select id="org"><option ${state.settings.org==="臺灣運動健康科技學會"?"selected":""}>臺灣運動健康科技學會</option><option ${state.settings.org==="臺北市立大學"?"selected":""}>臺北市立大學</option></select></div><div class="field full"><label>費用類別</label><select id="feeType"><option value="2000">鐘點費 2,000 元</option><option value="2500">出席費 2,500 元</option><option value="196">工作費 196 元／小時</option><option value="custom">主持人費或自訂</option></select></div><div class="field"><label>單價</label><input id="rate" type="number" value="2000"></div><div class="field"><label>數量／小時</label><input id="qty" type="number" min="1" value="1"></div><div class="field full"><label>勞務內容</label><input id="service" value="專家講座鐘點費"></div><div class="field"><label>日期</label><input id="receiptDate" type="date" value="${today}"></div><div class="field"><label>付款方式</label><select id="payment"><option>匯款</option><option>現金</option><option>支票</option></select></div><div class="field full"><button class="btn primary" id="printReceipt" type="button">列印／另存 PDF</button></div><div class="field full"><div class="notice">電子簽名連結需要雲端資料庫與受控存取；本版先完成簽名欄位與列印流程，不在公開靜態網站收集真實簽名。</div></div></div></div><div id="receiptPreview"></div></div>`;function update(){person=state.people.find(p=>p.id===document.querySelector("#receiptPerson").value)||{};let org=document.querySelector("#org").value,amount=Number(document.querySelector("#rate").value)*Number(document.querySelector("#qty").value),date=document.querySelector("#receiptDate").value;document.querySelector("#receiptPreview").innerHTML=`<article class="receipt-paper"><div class="receipt-head"><div class="receipt-logo">${org==="臺北市立大學"?"北市大":"運健"}</div><h2>${org}</h2><h3>${org==="臺北市立大學"?"領據":"勞務報酬單"}</h3></div><div class="receipt-table"><div class="receipt-line"><div class="receipt-label">姓名</div><div class="receipt-value">${esc(person.name||"尚未選擇")}</div></div><div class="receipt-line"><div class="receipt-label">身分證字號</div><div class="receipt-value">${esc(person.idNo||"")}</div></div><div class="receipt-line"><div class="receipt-label">戶籍地址</div><div class="receipt-value">${esc(person.address||"")}</div></div><div class="receipt-line"><div class="receipt-label">聯絡電話</div><div class="receipt-value">${esc(person.phone||"")}</div></div><div class="receipt-line"><div class="receipt-label">勞務內容</div><div class="receipt-value">${esc(document.querySelector("#service").value)}</div></div><div class="receipt-line"><div class="receipt-label">應付金額</div><div class="receipt-value money"><strong>${money(amount)}</strong>（單價 ${money(document.querySelector("#rate").value)} × ${document.querySelector("#qty").value}）</div></div><div class="receipt-line"><div class="receipt-label">付款資料</div><div class="receipt-value">${esc(document.querySelector("#payment").value)}　${esc(person.bank||"")} ${esc(person.branch||"")}　${esc(person.account||"")}</div></div><div class="receipt-line"><div class="receipt-label">日期</div><div class="receipt-value">${esc(date)}</div></div></div><div class="signature-box"><div><strong>個人資料使用同意</strong><p style="font-size:12px;line-height:1.7">本人確認上述資料無誤，並同意供款項核發、核銷、報稅及聯繫使用。</p></div><div><div class="signature-pad">${esc(person.signature||"簽名／簽章")}</div><p style="font-size:11px;text-align:center">領款人簽名</p></div></div></article>`;}document.querySelectorAll("#receiptPerson,#org,#feeType,#rate,#qty,#service,#receiptDate,#payment").forEach(el=>el.oninput=()=>{if(el.id==="feeType"&&el.value!=="custom")document.querySelector("#rate").value=el.value;if(el.id==="org"){state.settings.org=el.value;save();}update();});document.querySelector("#printReceipt").onclick=()=>window.print();update();}
function chineseMoneySlots(amount){
 const digits=["零","壹","貳","參","肆","伍","陸","柒","捌","玖"];
 const n=Math.max(0,Math.min(99999,Math.round(Number(amount)||0))).toString().padStart(5,"0").split("").map(Number);
 return [[digits[n[0]],"萬"],[digits[n[1]],"仟"],[digits[n[2]],"佰"],[digits[n[3]],"拾"],[digits[n[4]],"元"]];
}
function moneySlotMarkup(amount){return chineseMoneySlots(amount).map(([d,u])=>`<span class="ut-money-digit">${d}</span><span class="ut-money-unit">${u}</span>`).join("");}
function rocDateParts(date){const d=date?new Date(`${date}T00:00:00`):new Date();return {y:d.getFullYear()-1911,m:d.getMonth()+1,d:d.getDate()};}
function utaipeiReceipt(person,amount,date){
 const roc=rocDateParts(date),branch=esc(person.branch||""),account=esc(person.account||"");
 return `<article class="receipt-paper ut-receipt">
  <header class="ut-title">臺北市立大學&nbsp;&nbsp;領據</header>
  <section class="ut-form">
    <div class="ut-row"><div class="ut-label">應支</div><div class="ut-colon">：</div><div class="ut-currency">新台幣</div><div class="ut-money">${moneySlotMarkup(amount)}</div></div>
    <div class="ut-row"><div class="ut-label">代扣所得稅</div><div class="ut-colon">：</div><div class="ut-currency">新台幣</div><div class="ut-deduction"><span>0</span>&nbsp;元整</div></div>
    <div class="ut-row ut-health"><div class="ut-label">代扣2％健保補充保費</div><div class="ut-colon">：</div><div class="ut-currency">新台幣</div><div class="ut-deduction"><span>0</span>&nbsp;元整</div><div class="ut-health-note">（單筆給付基本工資以上，1千萬元以下，<br>代扣2％健保補充保險費）</div></div>
    <div class="ut-row"><div class="ut-label">實支</div><div class="ut-colon">：</div><div class="ut-currency">新台幣</div><div class="ut-money">${moneySlotMarkup(amount)}</div></div>
    <div class="ut-row ut-person"><div class="ut-label">具領人</div><div class="ut-colon">：</div><div class="ut-fill">${esc(person.name||"")}</div><div class="ut-phone-label">聯絡電話(手機)︰</div><div class="ut-fill phone">${esc(person.phone||"")}</div></div>
    <div class="ut-row"><div class="ut-label">身分證字號</div><div class="ut-colon">：</div><div class="ut-fill wide">${esc(person.idNo||"")}</div></div>
    <div class="ut-row ut-address"><div class="ut-label">戶籍所在地</div><div class="ut-colon">：</div><div class="ut-fill wide">${esc(person.address||"")}</div></div>
    <div class="ut-row ut-bank"><div class="ut-label">郵局局號</div><div class="ut-colon">：</div><div class="ut-fill bank">${branch}</div><div class="ut-bank-label">郵 局 帳 號:</div><div class="ut-fill account">${account}</div></div>
    <div class="ut-row ut-date"><span>中&nbsp;&nbsp;華&nbsp;&nbsp;民&nbsp;&nbsp;國</span><span class="ut-date-value">${roc.y}</span><span>年</span><span class="ut-date-value">${roc.m}</span><span>月</span><span class="ut-date-value">${roc.d}</span><span>日</span></div>
    <div class="ut-signature">具領人簽名 <span>${esc(person.signature||"")}</span>（簽章）</div>
  </section>
  <section class="ut-consent">
    <h3>個人資料提供同意書</h3>
    <p>本人同意並確認以下事項：</p>
    <p>本人所填寫之領據乃臺北市立大學為核發本人上述款項繕造印領清冊、費用領據業務使用。</p>
    <p>本人同意將領據內所填之個人資料（如姓名、身分證統一編號、手機電話號碼、郵局之局帳號及戶籍地址等）</p>
    <p>提供給臺北市立大學業務相關承辦單位繕製印領清冊與上述申請業務有關作業及公務上聯繫與服務之用，</p>
    <p>並於簽章欄親筆簽名。</p>
    <div class="ut-consent-sign">本人 <span>${esc(person.signature||"")}</span> （簽章）</div>
  </section>
 </article>`;
}
function societyReceipt(person,amount,date){return `<article class="receipt-paper"><div class="receipt-head"><div class="receipt-logo">運健</div><h2>臺灣運動健康科技學會</h2><h3>勞務報酬單</h3></div><div class="receipt-table"><div class="receipt-line"><div class="receipt-label">姓名</div><div class="receipt-value">${esc(person.name||"尚未選擇")}</div></div><div class="receipt-line"><div class="receipt-label">身分證字號</div><div class="receipt-value">${esc(person.idNo||"")}</div></div><div class="receipt-line"><div class="receipt-label">戶籍地址</div><div class="receipt-value">${esc(person.address||"")}</div></div><div class="receipt-line"><div class="receipt-label">聯絡電話</div><div class="receipt-value">${esc(person.phone||"")}</div></div><div class="receipt-line"><div class="receipt-label">勞務內容</div><div class="receipt-value">${esc(document.querySelector("#service").value)}</div></div><div class="receipt-line"><div class="receipt-label">應付金額</div><div class="receipt-value money"><strong>${money(amount)}</strong>（單價 ${money(document.querySelector("#rate").value)} × ${document.querySelector("#qty").value}）</div></div><div class="receipt-line"><div class="receipt-label">付款資料</div><div class="receipt-value">${esc(document.querySelector("#payment").value)}　${esc(person.bank||"")} ${esc(person.branch||"")}　${esc(person.account||"")}</div></div><div class="receipt-line"><div class="receipt-label">日期</div><div class="receipt-value">${esc(date)}</div></div></div><div class="signature-box"><div><strong>個人資料使用同意</strong><p style="font-size:12px;line-height:1.7">本人確認上述資料無誤，並同意供款項核發、核銷、報稅及聯繫使用。</p></div><div><div class="signature-pad">${esc(person.signature||"簽名／簽章")}</div><p style="font-size:11px;text-align:center">領款人簽名</p></div></div></article>`;}
function receiptsV2(){
 let person=state.people.find(p=>p.id===selectedPerson)||state.people[0]||{},today=new Date().toISOString().slice(0,10);
 content.innerHTML=`<div class="receipt-layout"><div class="card receipt-controls no-print"><div class="card-title"><div><h2>領據設定</h2><p>臺北市立大學格式依 113 空白領據範本重製</p></div></div><div class="form-grid"><div class="field full"><label>領款人</label><select id="receiptPerson"><option value="">請選擇委員</option>${state.people.map(p=>`<option value="${p.id}" ${p.id===person.id?"selected":""}>${esc(p.name)}</option>`)}</select></div><div class="field full"><label>抬頭與格式</label><select id="org"><option ${state.settings.org==="臺灣運動健康科技學會"?"selected":""}>臺灣運動健康科技學會</option><option ${state.settings.org==="臺北市立大學"?"selected":""}>臺北市立大學</option></select></div><div class="field full"><label>費用類別</label><select id="feeType"><option value="2000">鐘點費 2,000 元</option><option value="2500">出席費 2,500 元</option><option value="196">工作費 196 元／小時</option><option value="custom">主持人費或自訂</option></select></div><div class="field"><label>單價</label><input id="rate" type="number" min="0" value="2000"></div><div class="field"><label>數量／小時</label><input id="qty" type="number" min="1" value="1"></div><div class="field full"><label>勞務內容</label><input id="service" value="專家講座鐘點費"></div><div class="field"><label>日期</label><input id="receiptDate" type="date" value="${today}"></div><div class="field"><label>付款方式</label><select id="payment"><option>匯款</option><option>現金</option><option>支票</option></select></div><div class="field full"><button class="btn primary" id="printReceipt" type="button">列印／另存 PDF</button></div><div class="field full"><div class="notice">臺北市立大學版已依範本邏輯保留代扣欄位，目前依你的設定預設為 0 元。</div></div></div></div><div id="receiptPreview"></div></div>`;
 function update(){
  person=state.people.find(p=>p.id===document.querySelector("#receiptPerson").value)||{};
  const org=document.querySelector("#org").value,amount=Number(document.querySelector("#rate").value)*Number(document.querySelector("#qty").value),date=document.querySelector("#receiptDate").value;
  document.querySelector("#receiptPreview").innerHTML=org==="臺北市立大學"?utaipeiReceipt(person,amount,date):societyReceipt(person,amount,date);
 }
 document.querySelectorAll("#receiptPerson,#org,#feeType,#rate,#qty,#service,#receiptDate,#payment").forEach(el=>el.oninput=()=>{if(el.id==="feeType"&&el.value!=="custom")document.querySelector("#rate").value=el.value;if(el.id==="org"){state.settings.org=el.value;save();}update();});
 document.querySelector("#printReceipt").onclick=()=>window.print();update();
}
function projectCategoryOptions(value=""){const names=[...new Set([...state.projects.map(p=>p.name),...state.people.map(p=>p.projectCategory).filter(Boolean)])];return `<option value="">尚未分類</option>${names.map(n=>`<option ${n===value?"selected":""}>${esc(n)}</option>`).join("")}`;}
function expertsV2(){
 content.innerHTML=`<div class="toolbar"><div class="toolbar-left"><button class="btn primary" id="addPerson">+新增委員</button><label class="btn" for="peopleCsv">匯入名單 CSV<input id="peopleCsv" type="file" accept=".csv" hidden></label></div><div class="toolbar-right"><span class="kpi-note">★ 可設為領據常用名單</span></div></div><div class="notice" style="margin-bottom:18px">委員可標註所屬計畫類別並加入常用名單；身分證、戶籍與銀行資料仍只儲存於本機瀏覽器。</div><div class="card"><div class="table-wrap"><table><thead><tr><th>常用</th><th>姓名</th><th>計畫類別</th><th>電話</th><th>Email</th><th>身分證</th><th></th></tr></thead><tbody>${state.people.length?state.people.slice().sort((a,b)=>Number(!!b.favorite)-Number(!!a.favorite)||String(a.name).localeCompare(String(b.name),"zh-Hant")).map(p=>`<tr><td><button class="favorite-toggle ${p.favorite?"active":""}" data-favorite="${p.id}" title="${p.favorite?"移出常用名單":"加入常用名單"}">${p.favorite?"★":"☆"}</button></td><td><strong>${esc(p.name)}</strong></td><td><span class="tag">${esc(p.projectCategory||"尚未分類")}</span></td><td>${esc(p.phone||"—")}</td><td>${esc(p.email||"—")}</td><td>${p.idNo?esc(p.idNo.slice(0,3)+"•••••"+p.idNo.slice(-2)):"—"}</td><td><button class="btn small" data-person="${p.id}">編輯／製作領據</button></td></tr>`).join(""):`<tr><td colspan="7"><div class="empty-state"><strong>尚無專家委員</strong>新增委員後，可標註計畫類別並加入常用名單。</div></td></tr>`}</tbody></table></div></div>`;
 document.querySelector("#addPerson").onclick=()=>personModalV2();
 document.querySelectorAll("[data-person]").forEach(b=>b.onclick=()=>personModalV2(state.people.find(p=>p.id===b.dataset.person)));
 document.querySelectorAll("[data-favorite]").forEach(b=>b.onclick=()=>{const p=state.people.find(x=>x.id===b.dataset.favorite);p.favorite=!p.favorite;save();expertsV2();});
}
function personModalV2(p){
 const edit=!!p;
 modal(`<div class="modal-head"><h2>${edit?"委員資料":"新增委員"}</h2><button class="close" data-close>&times;</button></div><form id="personFormV2" class="form-grid"><div class="field"><label>姓名</label><input required name="name" value="${esc(p?.name||"")}"></div><div class="field"><label>出生年月日</label><input type="date" name="birthday" value="${esc(p?.birthday||"")}"></div><div class="field full"><label>計畫類別</label><select name="projectCategory">${projectCategoryOptions(p?.projectCategory||"")}</select></div><div class="field full favorite-field"><label><input type="checkbox" name="favorite" ${p?.favorite?"checked":""}> 加入常用名單</label></div><div class="field"><label>身分證字號／居留證</label><input name="idNo" value="${esc(p?.idNo||"")}"></div><div class="field"><label>聯絡電話</label><input name="phone" value="${esc(p?.phone||"")}"></div><div class="field"><label>Email</label><input type="email" name="email" value="${esc(p?.email||"")}"></div><div class="field"><label>戶籍地址</label><input name="address" value="${esc(p?.address||"")}"></div><div class="field"><label>銀行／郵局</label><input name="bank" value="${esc(p?.bank||"")}"></div><div class="field"><label>分行／局號</label><input name="branch" value="${esc(p?.branch||"")}"></div><div class="field"><label>帳號</label><input name="account" value="${esc(p?.account||"")}"></div><div class="field"><label>戶名</label><input name="accountName" value="${esc(p?.accountName||"")}"></div><div class="field full"><button class="btn primary">儲存委員</button>${edit?` <button type="button" class="btn gold" id="toReceiptV2">帶入製作領據</button>`:""}</div></form>`);
 document.querySelector("#personFormV2").onsubmit=e=>{e.preventDefault();const form=new FormData(e.target),data=Object.fromEntries(form);data.favorite=e.target.elements.favorite.checked;if(edit)Object.assign(p,data);else state.people.push({id:crypto.randomUUID(),...data});save();closeModal();expertsV2();};
 if(edit)document.querySelector("#toReceiptV2").onclick=()=>{selectedPerson=p.id;closeModal();current="receipts";shell();};
}
function utaipeiReceiptWithMeeting(person,amount,date,meeting){return utaipeiReceipt(person,amount,date).replace('<section class="ut-form">',`<section class="ut-form"><div class="ut-meeting"><strong>會議名稱：</strong><span>${esc(meeting||"")}</span></div>`);}
function societyReceiptWithMeeting(person,amount,date,meeting){return societyReceipt(person,amount,date).replace('<div class="receipt-table">',`<div class="receipt-table"><div class="receipt-line"><div class="receipt-label">會議名稱</div><div class="receipt-value">${esc(meeting||"")}</div></div>`);}
function receiptPeople(filter=""){return state.people.filter(p=>!filter||p.projectCategory===filter).sort((a,b)=>Number(!!b.favorite)-Number(!!a.favorite)||String(a.name).localeCompare(String(b.name),"zh-Hant"));}
