 let person=state.people.find(p=>p.id===selectedPerson)||state.people[0]||{},today=new Date().toISOString().slice(0,10);
 const categories=[...new Set(state.people.map(p=>p.projectCategory).filter(Boolean))];
 content.innerHTML=`<div class="receipt-layout"><div class="card receipt-controls no-print"><div class="card-title"><div><h2>領據設定</h2><p>同一會議可套用設定並連續製作多位受款者領據</p></div></div><div class="form-grid"><div class="field full"><label>會議名稱</label><input id="meetingName" required placeholder="例如：115 年度第 1 次專家諮詢會議"></div><div class="field full"><label>常用名單·計畫類別</label><select id="projectFilter"><option value="">全部計畫類別</option>${categories.map(c=>`<option>${esc(c)}</option>`).join("")}</select></div><div class="field full"><div class="common-list" id="commonList"></div></div><div class="field full"><label>領款人</label><select id="receiptPerson"></select></div><div class="field full"><label>抬頭與格式</label><select id="org"><option ${state.settings.org==="臺灣運動健康科技學會"?"selected":""}>臺灣運動健康科技學會</option><option ${state.settings.org==="臺北市立大學"?"selected":""}>臺北市立大學</option></select></div><div class="field full"><label>費用類別</label><select id="feeType"><option value="2000">鐘點費 2,000 元</option><option value="2500">出席費 2,500 元</option><option value="196">工作費 196 元／小時</option><option value="custom">主持人費或自訂</option></select></div><div class="field"><label>單價</label><input id="rate" type="number" min="0" value="2000"></div><div class="field"><label>數量／小時</label><input id="qty" type="number" min="1" value="1"></div><div class="field full"><label>勞務內容</label><input id="service" value="專家講座鐘點費"></div><div class="field"><label>日期</label><input id="receiptDate" type="date" value="${today}"></div><div class="field"><label>付款方式</label><select id="payment"><option>匯款</option><option>現金</option><option>支票</option></select></div><div class="field full receipt-actions"><button class="btn primary" id="printReceipt" type="button">列印／另存 PDF</button><button class="btn gold" id="applyNext" type="button">套用並新增下一位</button></div><div class="field full"><p class="apply-message" id="applyMessage"></p></div></div></div><div id="receiptPreview"></div></div>`;
 const personSelect=document.querySelector("#receiptPerson"),commonList=document.querySelector("#commonList");
 function renderPeople(filter=document.querySelector("#projectFilter").value){const people=receiptPeople(filter),current=personSelect.value||person.id||"";personSelect.innerHTML=`<option value="">請選擇受款者</option>${people.map(p=>`<option value="${p.id}" ${p.id===current?"selected":""}>${p.favorite?"★ ":""}${esc(p.name)}${p.projectCategory?` · ${esc(p.projectCategory)}`:""}</option>`).join("")}`;commonList.innerHTML=people.filter(p=>p.favorite).length?people.filter(p=>p.favorite).map(p=>`<button type="button" class="common-person" data-common="${p.id}"><span>★</span>${esc(p.name)}<small>${esc(p.projectCategory||"未分類")}</small></button>`).join(""):`<span class="common-empty">此類別尚無常用委員，可在「專家委員」頁面設定。</span>`;document.querySelectorAll("[data-common]").forEach(b=>b.onclick=()=>{personSelect.value=b.dataset.common;selectedPerson=b.dataset.common;update();});}
 function update(){person=state.people.find(p=>p.id===personSelect.value)||{};const org=document.querySelector("#org").value,amount=Number(document.querySelector("#rate").value)*Number(document.querySelector("#qty").value),date=document.querySelector("#receiptDate").value,meeting=document.querySelector("#meetingName").value;document.querySelector("#receiptPreview").innerHTML=org==="臺北市立大學"?utaipeiReceiptWithMeeting(person,amount,date,meeting):societyReceiptWithMeeting(person,amount,date,meeting);}
