 document.querySelector("#printReceipt").onclick=()=>window.print();
 document.querySelector("#applyNext").onclick=()=>{if(!document.querySelector("#meetingName").value.trim()){document.querySelector("#meetingName").focus();document.querySelector("#applyMessage").textContent="請先輸入會議名稱。";return;}if(!personSelect.value){personSelect.focus();document.querySelector("#applyMessage").textContent="請先選擇本位受款者。";return;}state.receipts.push({id:crypto.randomUUID(),personId:personSelect.value,meetingName:document.querySelector("#meetingName").value.trim(),org:document.querySelector("#org").value,rate:Number(document.querySelector("#rate").value),qty:Number(document.querySelector("#qty").value),service:document.querySelector("#service").value,date:document.querySelector("#receiptDate").value,payment:document.querySelector("#payment").value,createdAt:new Date().toISOString()});save();const name=person.name;personSelect.value="";selectedPerson="";person={};document.querySelector("#applyMessage").textContent=`已保留會議設定並完成 ${name} 的套用記錄，請選擇下一位受款者。`;update();};
 update();
