const excelLetters=Array.from({length:defenseWorkbook.maxCol},(_,i)=>{let n=i+1,s="";while(n){n--;s=String.fromCharCode(65+n%26)+s;n=Math.floor(n/26);}return s;});
function defenseCellValue(coord){const override=state.defenseSheetOverrides?.[coord];return override!==undefined?override:defenseWorkbook.cells[coord]?.value;}
function numericSheetValue(coord){const value=defenseCellValue(coord);if(typeof value==="number")return value;const parsed=Number(String(value??"").replaceAll(",","").replaceAll("$","").trim());return Number.isFinite(parsed)?parsed:0;}
function defenseSheetSpent(){if(!state?.defenseSheetOverrides)return Number(defenseWorkbook.summary.executed||0);return defenseWorkbook.detailRows.reduce((sum,row)=>sum+excelLetters.slice(3,35).reduce((rowSum,col)=>rowSum+numericSheetValue(`${col}${row}`),0),0);}
function excelColor(value){if(!value)return "transparent";if(value.startsWith("indexed:")){const map={0:"#000000",1:"#ffffff",2:"#ff0000",3:"#00ff00",4:"#0000ff",5:"#ffff00",6:"#ff00ff",7:"#00ffff",8:"#000000",9:"#ffffff",10:"#ff0000",11:"#00ff00",12:"#0000ff",13:"#ffff00",14:"#ff00ff",15:"#00ffff",22:"#c0c0c0",64:"#ffffff"};return map[value.split(":")[1]]||"#ffffff";}if(value.startsWith("theme:")){const map={0:"#ffffff",1:"#000000",2:"#e7e6e6",3:"#44546a",4:"#5b9bd5",5:"#ed7d31",6:"#a5a5a5",7:"#ffc000",8:"#4472c4",9:"#70ad47"};return map[value.split(":")[1]]||"#ffffff";}return `#${value}`;}
function excelBorder(side){if(!side)return "none";const widths={hair:1,thin:1,medium:2,thick:3,double:3,dashed:1,dotted:1,dashDot:1};const line=side.style==="double"?"double":side.style?.includes("dash")?"dashed":side.style==="dotted"?"dotted":"solid";return `${widths[side.style]||1}px ${line} ${excelColor(side.color)||"#777"}`;}
function excelStyle(styleId){const s=defenseWorkbook.styles[styleId]||{},f=s.font||{},a=s.alignment||{},b=s.border||{};return [`font-family:${f.name?`'${String(f.name).replaceAll("'","")}'`:"Arial"},sans-serif`,`font-size:${f.size||10}pt`,`font-weight:${f.bold?700:400}`,`font-style:${f.italic?"italic":"normal"}`,`text-decoration:${f.underline?"underline":"none"}`,`color:${excelColor(f.color)==="transparent"?"#111":excelColor(f.color)}`,`background:${excelColor(s.fill)}`,`text-align:${a.horizontal==="center"?"center":a.horizontal==="right"?"right":"left"}`,`vertical-align:${a.vertical==="top"?"top":a.vertical==="center"?"middle":"bottom"}`,`white-space:${a.wrap?"normal":"nowrap"}`,`border-top:${excelBorder(b.top)}`,`border-right:${excelBorder(b.right)}`,`border-bottom:${excelBorder(b.bottom)}`,`border-left:${excelBorder(b.left)}`].join(";");}
function displayExcelValue(value,numberFormat="General"){if(value===null||value===undefined)return "";if(typeof value!=="number")return String(value);if(numberFormat.includes("%"))return `${(value*100).toFixed(numberFormat.includes("0.00")?2:numberFormat.includes("0.0")?1:0)}%`;if(/[#,]##0/.test(numberFormat)||numberFormat.includes("#,##0"))return new Intl.NumberFormat("zh-TW",{maximumFractionDigits:numberFormat.includes(".00")?2:0}).format(value);return String(value);}
function mergeMaps(){const anchors=new Map(),covered=new Set();for(const m of defenseWorkbook.merges){anchors.set(m.start,m);for(let r=m.minRow;r<=m.maxRow;r++)for(let c=m.minCol;c<=m.maxCol;c++){const coord=`${excelLetters[c-1]}${r}`;if(coord!==m.start)covered.add(coord);}}return {anchors,covered};}
function defenseExcelTable(){const {anchors,covered}=mergeMaps(),hidden=new Set(defenseWorkbook.hiddenRows);let html=`<div class="excel-scroll"><table class="excel-sheet"><colgroup><col class="row-number-col">${defenseWorkbook.columnWidths.map(w=>`<col style="width:${Math.max(34,Math.round(w*7.1))}px">`).join("")}</colgroup><thead><tr><th class="excel-corner"></th>${excelLetters.map(l=>`<th class="excel-column-letter">${l}</th>`).join("")}</tr></thead><tbody>`;for(let row=1;row<=defenseWorkbook.maxRow;row++){if(hidden.has(row))continue;html+=`<tr style="height:${Math.max(20,Math.round(defenseWorkbook.rowHeights[row-1]*1.35))}px"><th class="excel-row-number">${row}</th>`;for(let col=1;col<=defenseWorkbook.maxCol;col++){const coord=`${excelLetters[col-1]}${row}`;if(covered.has(coord))continue;const cell=defenseWorkbook.cells[coord]||{value:null,style:0},merge=anchors.get(coord),value=defenseCellValue(coord),format=defenseWorkbook.styles[cell.style]?.numberFormat||"General";html+=`<td data-excel-cell="${coord}" contenteditable="true" spellcheck="false" ${merge?`rowspan="${merge.rowspan}" colspan="${merge.colspan}"`:""} style="${excelStyle(cell.style)}" title="${esc(cell.formula||coord)}">${esc(displayExcelValue(value,format))}</td>`;}html+="</tr>";}return html+="</tbody></table></div>";}
function defensePivot(){return excelLetters.slice(3,35).map((col,index)=>{const name=defenseCellValue(`${col}9`)||`科目 ${index+1}`,budget=numericSheetValue(`${col}11`),adjusted=numericSheetValue(`${col}39`),used=defenseWorkbook.detailRows.reduce((sum,row)=>sum+numericSheetValue(`${col}${row}`),0),remaining=adjusted-used,pct=adjusted?used/adjusted*100:0;return `<tr><td>${index<12?"人事費":index===31?"行管費":"業務費"}</td><td>${esc(name)}</td><td class="money">${money(budget)}</td><td class="money">${money(adjusted-budget)}</td><td class="money">${money(adjusted)}</td><td class="money">${money(used)}</td><td class="money">${money(remaining)}</td><td>${pct.toFixed(1)}%</td></tr>`;}).join("");}
function ledgerV2(){const p=state.projects.find(x=>x.id===selectedProject)||state.projects[0];if(p.id!=="defense"){ledger();return;}const used=spent(p),remaining=Number(p.budget)-used,pct=p.budget?used/p.budget*100:0;content.innerHTML=`<div class="toolbar"><div class="toolbar-left"><select class="btn" id="projectSelect">${state.projects.map(x=>`<option value="${x.id}" ${x.id===p.id?"selected":""}>${esc(x.name)}</option>`)}</select><span class="source-badge">來源：${esc(defenseWorkbook.source)} · ${esc(defenseWorkbook.sheetName)}</span></div><div class="toolbar-right"><button class="btn" id="resetDefenseSheet">還原 Excel 原始值</button></div></div><div class="grid kpis excel-kpis"><div class="card kpi"><div class="kpi-label">計畫核定金額</div><div class="kpi-value">${money(p.budget)}</div></div><div class="card kpi"><div class="kpi-label">已執行／已核銷金額</div><div class="kpi-value">${money(used)}</div><div class="kpi-note">來源工作表既有 ${defenseWorkbook.detailRows.length} 筆有金額明細</div></div><div class="card kpi"><div class="kpi-label">未核銷餘額</div><div class="kpi-value">${money(remaining)}</div></div><div class="card kpi"><div class="kpi-label">計畫執行率</div><div class="kpi-value">${pct.toFixed(1)}%</div><div class="progress ${pct>=state.settings.warning?"warn":""}"><i style="width:${Math.min(100,pct)}%"></i></div></div></div><div class="card excel-pivot-card"><div class="card-title"><div><h2>預算科目樞紐分析</h2><p>原預算、勻支後、已核銷與未核銷金額均取自 Excel 對應欄列</p></div></div><div class="table-wrap"><table><thead><tr><th>類別</th><th>項目</th><th>原預算金額</th><th>勻支調整</th><th>勻支後金額</th><th>核銷金額</th><th>未核銷金額</th><th>執行率</th></tr></thead><tbody>${defensePivot()}</tbody></table></div></div><div class="card excel-ledger-card"><div class="card-title"><div><h2>115年防護計畫經費勻支明細表</h2><p>完整呈現原工作表 281 列 × 46 欄；橫向捲動查看全部科目，點選儲存格可直接修改並保存於本機瀏覽器。</p></div><span class="status">Excel 完整格式</span></div>${defenseExcelTable()}</div>`;document.querySelector("#projectSelect").onchange=e=>{selectedProject=e.target.value;ledgerV2();};document.querySelectorAll("[data-excel-cell]").forEach(cell=>cell.onblur=()=>{state.defenseSheetOverrides={...(state.defenseSheetOverrides||{}),[cell.dataset.excelCell]:cell.textContent.trim()};save();ledgerV2();});document.querySelector("#resetDefenseSheet").onclick=()=>{if(confirm("確定要清除本機修改並還原 Excel 原始值嗎？")){state.defenseSheetOverrides={};save();ledgerV2();}};}
